struct Resource {
    int id;
    ~Resource() { /* Custom Cleanup Logic */ }
};

// 1. Pre-allocated memory segment (Arena)
alignas(Resource) char arena[sizeof(Resource)];

// 2. Obtain pointer to the buffer
void* buffer = static_cast<void*>(arena);

// 3. Placement New: Construct Resource in 'buffer'
Resource* r1 = new (buffer) Resource{1};

// Standard delete is illegal for placement new objects.
// delete r1; // ERROR: Would attempt heap deallocation.

// 4. Manual Destructor Call (CRITICAL for cleanup)
r1->~Resource();

// Arena is now reusable.
Resource* r2 = new (arena) Resource{2};
r2->~Resource();
